package com.causalops.demo;
import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.web.bind.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;
@SpringBootApplication @RestController public class DemoApplication {static volatile int latency=0;final JdbcTemplate db;DemoApplication(JdbcTemplate d){db=d;}public static void main(String[]x){SpringApplication.run(DemoApplication.class,x);}@GetMapping("/inventory/{sku}") Object inventory(@PathVariable String sku)throws Exception{if(latency>0)Thread.sleep(latency);Integer available=db.queryForObject("select quantity from inventory where sku=?",Integer.class,sku);return Map.of("sku",sku,"available",available==null?0:available);}@PostMapping("/internal/fault") Object fault(@RequestBody Map<String,Object>x){latency=((Number)x.getOrDefault("latencyMs",0)).intValue();return Map.of("latencyMs",latency);}@GetMapping("/business") Object business()throws Exception{return inventory("sku-demo");}}
